import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { FormGroupComponent } from "../../../../shared/generic-form/form-group/form-group.component";
import { CurrencyPipe, DatePipe } from '@angular/common';
import { Convenio } from '../../../../models/convenio';
import { CollapsableComponent } from "../../../../shared/collapsable/collapsable.component";
import { CreditoService } from '../../../../controllers/credito.service';
import { RouterLink } from '@angular/router';

@Component({
    selector: 'app-view-relacion-convenios',
    imports: [
    CurrencyPipe,
    DatePipe,
    CollapsableComponent,
    RouterLink
],
    templateUrl: './view-relacion-convenios.component.html',
    styleUrl: './view-relacion-convenios.component.css'
})
export class ViewRelacionConveniosComponent {
  @Input() credito!:Credito
  convenios:Convenio[]=[]
  creditoReestructura?:Credito

  constructor(
    private creditoController: CreditoService,
  ){}

  ngOnInit(){
    this.setConvenios()
    this.checarSiFueReestructurado()
  }

  private setConvenios(){
    this.convenios = this.credito.convenios ?? [];
    this.convenios.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
  }

  ngOnChanges(changes:SimpleChanges){
    if(changes['credito'] && this.credito.id != changes['credito'].previousValue?.id){
      this.setConvenios()
      this.checarSiFueReestructurado()
    }
  }

  private async checarSiFueReestructurado(){
    if(!this.credito.folio_reestructura){
      this.creditoReestructura=undefined
      return
    }
    if(this.creditoReestructura?.folio == this.credito.folio_reestructura) return;
    this.creditoReestructura = await this.creditoController.first({folio:this.credito.folio_reestructura},[],{},false)
  }
}
